pages.css:
.gallery-intro p{max-width:46rem;color:var(--color-text-muted);font-size:1.05rem;}
.gallery-category{margin-bottom:var(--space-lg);}
#gallery-grid h2{margin-top:var(--space-md);}
#gallery-grid h2:first-of-type{margin-top:0;}
.gallery-figure{margin:0;background:var(--color-white);border:1px solid var(--color-border);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column;}
.gallery-figure img{width:100%;height:12rem;object-fit:cover;display:block;}
.gallery-figure figcaption{padding:0.6rem 0.8rem;font-size:0.95rem;color:var(--color-text-muted);}
.gallery-cta{text-align:center;background:var(--color-dark-bg);color:var(--color-white);}
.gallery-cta h2{color:var(--color-accent-on-dark);}
.gallery-cta p{max-width:36rem;margin:0 auto var(--space-sm);color:var(--color-white);}
@media (max-width:600px){.gallery-figure img{height:10rem;}}
@media (min-width:601px){.gallery-figure img{height:13rem;}}

